#include "ModalSelfCal.h"
#include "research_hook.h"
#include "RX.cpp"
#include <fstream>
#include <iostream>
#include <chrono>
#include <cstring>
using Vec=rx::Vec;
template<class T>T rd(std::istream&f){T v{};f.read((char*)&v,sizeof(v));if(!f)throw std::runtime_error("truncated input");return v;}
template<class T>void wr(std::ostream&f,T v){f.write((const char*)&v,sizeof(v));}
std::string rs(std::istream&f){auto n=rd<uint32_t>(f);std::string s(n,' ');f.read(s.data(),n);return s;}
void ws(std::ostream&f,const std::string&s){wr<uint32_t>(f,s.size());f.write(s.data(),s.size());}
void wv(std::ostream&f,const Vec&v){f.write((const char*)v.data(),v.size()*8);}
struct Frame{int64_t t;Vec x,y;};
struct Bundle{std::unique_ptr<RXState> state;rx::Context ctx;Bundle(const std::string&m,const std::vector<std::string>&n,const std::string&dev,const std::map<int64_t,Vec>&coords):ctx(m,n){ctx.coords=coords;state=std::make_unique<RXState>();std::string e;if(!state->Init(dev,n,&e,true))throw std::runtime_error(e);}};
const std::vector<std::string> diagNames={"v0_1","v0_2","v0_3","v_used_1","v_used_2","v_used_3","n_frame_learn_valid","n_learn_points","n_history","gate","modes_ready","modes_from_tonight","enhancement_active","fallback_code","effective_learning_count","downweighted_below_half","max_leverage","qualified_current_refs","rejected_refs","delta_v_norm","learning_RMS_before_mm","learning_RMS_after_mm","temporal_reset","spatial_LOPO_energy_gain","spatial_condition_bound","process_us","Y_mismatch_count","n_corrected","max_nontarget_all_delta_mm","max_nontarget_key_delta_mm"};
struct Writer{std::ofstream f;std::vector<int> ix;Writer(const std::string&path,const std::vector<std::string>&names,const std::vector<std::string>&modes,uint32_t frames,bool compact):f(path,std::ios::binary){for(int i=0;i<int(names.size());i++)if(!compact||rx::key(names[i]))ix.push_back(i);wr<uint32_t>(f,ix.size());for(int i:ix)ws(f,names[i]);wr<uint32_t>(f,modes.size());for(auto&m:modes)ws(f,m);wr<uint32_t>(f,diagNames.size());for(auto&n:diagNames)ws(f,n);wr<uint32_t>(f,frames);}
void row(int64_t t,const Vec&x,const Vec&y,const Vec&oy,const std::vector<Vec>&out,const std::vector<Vec>&loo,const std::vector<Vec>&diag){wr<int64_t>(f,t);for(auto* v:{&x,&y,&oy})for(int i:ix)wr<double>(f,(*v)[i]);for(size_t m=0;m<out.size();m++){for(int i:ix)wr<double>(f,out[m][i]);for(int i:ix)wr<double>(f,loo[m][i]);wv(f,diag[m]);}}};
double elapsed(std::chrono::steady_clock::time_point a){return std::chrono::duration<double,std::micro>(std::chrono::steady_clock::now()-a).count();}
template<class Info>Vec diagVec(const Info&info,const rx::Diag&d,double us,int ym){Vec out=d.v0;out.insert(out.end(),d.v.begin(),d.v.end());for(double v:{double(info.n_frame_learn_valid),double(info.n_learn_points),double(info.n_history),info.gate,double(info.modes_ready),double(info.modes_from_tonight),double(d.active),double(d.fallback),(d.neff>0?d.neff:info.n_frame_learn_valid),d.down,d.maxh,d.refs,d.refreject,d.dv,d.rms0,d.rms1,d.reset,d.bscore,d.bcond,us,double(ym),double(info.n_corrected),0.,0.})out.push_back(v);if(out.size()!=diagNames.size())throw std::runtime_error("diag shape");return out;}
struct Result{std::vector<Vec> out,loo,diag;Vec y;};
Result process(ModalSelfCalState&base,std::vector<std::unique_ptr<Bundle>>&bs,const Frame&f){std::string err;ModalSelfCalResult r;auto tick=std::chrono::steady_clock::now();if(!base.Process(f.t,f.x,f.y,&r,&err))throw std::runtime_error(err);double us=elapsed(tick);Result out;out.y=r.y;out.out.push_back(r.x);out.loo.push_back(Vec(f.x.size(),NAN));rx::Diag bd;bd.v0.assign(r.info_x.v,r.info_x.v+3);bd.v=bd.v0;out.diag.push_back(diagVec(r.info_x,bd,us,0));for(auto&b:bs){RXResult z;b->ctx.diag=rx::Diag();b->ctx.loo.assign(f.x.size(),NAN);rx::current=&b->ctx;tick=std::chrono::steady_clock::now();if(!b->state->Process(f.t,f.x,f.y,&z,&err))throw std::runtime_error(err);us=elapsed(tick);rx::current=nullptr;int ym=0;for(size_t i=0;i<r.y.size();i++)if(std::memcmp(&r.y[i],&z.y[i],8))ym++;if(ym)throw std::runtime_error("Y mismatch");if(b->ctx.mode=="identity")for(size_t i=0;i<r.x.size();i++)if(std::memcmp(&r.x[i],&z.x[i],8))throw std::runtime_error("patched identity differs original");out.out.push_back(z.x);out.loo.push_back(b->ctx.loo);out.diag.push_back(diagVec(z.info_x,b->ctx.diag,us,ym));}return out;}
int main(int argc,char**argv){static char logbuffer[1<<20];std::setvbuf(stderr,logbuffer,_IOFBF,sizeof(logbuffer));try{
 if(argc!=6)throw std::runtime_error("input_prefix output_directory device modes_csv normal_or_inject");std::string prefix=argv[1],dir=argv[2],dev=argv[3],stage=argv[5];std::vector<std::string> names,modes={"V51"};std::stringstream ms(argv[4]);std::string m;while(std::getline(ms,m,','))modes.push_back(m);
 std::ifstream inp(prefix+".bin",std::ios::binary);auto n=rd<uint32_t>(inp);for(uint32_t i=0;i<n;i++)names.push_back(rs(inp));auto nf=rd<uint32_t>(inp);std::vector<Frame> frames;for(uint32_t f=0;f<nf;f++){Frame q;q.t=rd<int64_t>(inp);for(uint32_t i=0;i<n;i++)q.x.push_back(rd<double>(inp));for(uint32_t i=0;i<n;i++)q.y.push_back(rd<double>(inp));frames.push_back(q);}
 std::map<int64_t,Vec> coords;std::ifstream cf(prefix+".coords");int nc;cf>>nc;for(int j=0;j<nc;j++){int64_t nid;cf>>nid;Vec uv;for(uint32_t i=0;i<2*n;i++){std::string tok;cf>>tok;uv.push_back(tok=="nan"?NAN:std::stod(tok));}coords[nid]=uv;}
 ModalSelfCalState base;std::string err;if(!base.Init(dev,names,&err,true))throw std::runtime_error(err);std::vector<std::unique_ptr<Bundle>> bs;for(size_t j=1;j<modes.size();j++)bs.emplace_back(new Bundle(modes[j],names,dev,coords));
 struct Snapshot{size_t frame;int64_t onset;std::string original;std::vector<std::string> candidate;std::vector<rx::Context> context;Vec shape;std::vector<char> learn;int learner=-1;};std::vector<Snapshot> snapshots;std::vector<Result> control;Writer writer(dir+"/normal_"+dev+".bin",names,modes,nf,false);
 for(size_t j=0;j<frames.size();j++){
  // Snapshot immediately before first real >=03:00 frame of each study night.
  for(int64_t onset:{1793905200000LL,1793991600000LL})if(frames[j].t>=onset&&(j==0||frames[j-1].t<onset)){
   Snapshot snap;snap.frame=j;snap.onset=onset;int64_t ts;if(!base.ExportState(&snap.original,&ts,&err))throw std::runtime_error(err);for(auto&b:bs){std::string blob;if(!b->state->ExportState(&blob,&ts,&err))throw std::runtime_error(err);snap.candidate.push_back(blob);snap.context.push_back(b->ctx);}auto*s=bs[0]->state->impl_->x->research_impl();double scale=0,h=-1;for(uint32_t i=0;i<n;i++)if(rx::key(names[i])&&s->use[i])scale=std::max(scale,std::abs(s->A[i*3]));snap.learn=s->learn;snap.shape.assign(n,0);for(uint32_t i=0;i<n;i++)if(s->use[i]&&scale>0)snap.shape[i]=s->A[i*3]/scale;for(uint32_t i=0;i<n;i++)if(s->learn[i]&&bs[0]->ctx.lev[i]>h){h=bs[0]->ctx.lev[i];snap.learner=i;}snapshots.push_back(std::move(snap));
  }
  Result r=process(base,bs,frames[j]);writer.row(frames[j].t,frames[j].x,frames[j].y,r.y,r.out,r.loo,r.diag);control.push_back(std::move(r));
 }
 std::ofstream birth(dir+"/birth_"+dev+".csv");birth<<"method,night_id,point_index,learn,use,historical_explained_energy,residual_scale_mm,leverage,YJ_group_qualified,B_qualified,B_LOPO_gain,B_condition,n_history,history_frames,A1,A2,A3,baseline_mm,cbar_mm\n"<<std::setprecision(17);for(auto&b:bs)for(const Vec&row:b->ctx.birth){birth<<b->ctx.mode;for(double v:row)birth<<','<<v;birth<<'\n';}
 if(stage=="inject")for(auto&snap:snapshots){
  std::vector<std::string> scenarios;for(auto name:{"YXJ2","YXJ3","YXJ4","YXJ5","YXJ6"})for(auto amp:{"1","3"})scenarios.push_back(std::string(name)+"_step"+amp);
  for(auto s:{"YXJ_ramp1_1h","YXJ_ramp3_3h","single_ref1","single_ref3","multiple_ref1","multiple_ref3","coherent1","coherent3","learner1","learner3","learner_spike3","reference_spike3","modal_step1","modal_step3","modal_ramp3_3h","missing_refs","missing_learners","Y_settlement"})scenarios.push_back(s);
  for(auto&scenario:scenarios){
   ModalSelfCalState original;if(!original.Init(dev,names,&err,true))throw std::runtime_error(err);ModalSelfCalResumeInfo resume;if(!original.ImportState(snap.original,&resume,&err))throw std::runtime_error(err);std::vector<std::unique_ptr<Bundle>> injected;for(size_t j=1;j<modes.size();j++){injected.emplace_back(new Bundle(modes[j],names,dev,coords));RXResumeInfo ri;if(!injected.back()->state->ImportState(snap.candidate[j-1],&ri,&err))throw std::runtime_error(err);injected.back()->ctx=snap.context[j-1];}
   size_t last=snap.frame;while(last<frames.size()&&frames[last].t<snap.onset+4*3600000LL)last++;Writer out(dir+"/"+scenario+"_"+std::to_string(snap.onset)+"_"+dev+".bin",names,modes,last-snap.frame,true);int single=-1;for(uint32_t i=0;i<n;i++)if(rx::isref(names[i])){single=i;break;}for(uint32_t i=0;i<n;i++)if(names[i]=="YJ7")single=i;
   for(size_t j=snap.frame;j<last;j++){Frame f=frames[j];Vec truth(n,0);double amp=scenario.back()=='3'?3.:1.;double hrs=(f.t-snap.onset)/3600000.;bool first=j==snap.frame;
    for(uint32_t i=0;i<n;i++){bool target=false;double delta=0;if(scenario.rfind(names[i]+"_step",0)==0){target=true;delta=amp;}if(scenario.rfind("YXJ_ramp",0)==0&&names[i].rfind("YXJ",0)==0){target=true;delta=scenario=="YXJ_ramp1_1h"?std::min(1.,hrs):std::min(3.,hrs);}if(scenario.rfind("single_ref",0)==0&&int(i)==single){target=true;delta=amp;}if(scenario.rfind("multiple_ref",0)==0&&rx::isref(names[i])){target=true;delta=amp;}if(scenario.rfind("coherent",0)==0&&rx::key(names[i])){target=true;delta=amp;}if(scenario.rfind("learner",0)==0&&int(i)==snap.learner){target=true;delta=scenario=="learner_spike3"?(first?3.:0.):amp;}if(scenario=="reference_spike3"&&int(i)==single){target=true;delta=first?3.:0.;}if(scenario.rfind("modal",0)==0){target=true;delta=snap.shape[i]*(scenario=="modal_ramp3_3h"?std::min(3.,hrs):amp);}if(target&&std::isfinite(f.x[i])){f.x[i]+=delta;truth[i]=delta;}if(scenario=="missing_refs"&&rx::isref(names[i])&&hrs<1./6)f.x[i]=NAN;if(scenario=="missing_learners"&&snap.learn[i]&&hrs<1./6)f.x[i]=NAN;if(scenario=="Y_settlement"&&names[i]=="YXJ5"&&std::isfinite(f.y[i]))f.y[i]-=1.;}
    Result z=process(original,injected,f);for(size_t mi=0;mi<modes.size();mi++){double all=0,keys=0;for(uint32_t i=0;i<n;i++)if(truth[i]==0&&std::isfinite(z.out[mi][i])&&std::isfinite(control[j].out[mi][i])){double d=std::abs(z.out[mi][i]-control[j].out[mi][i]);all=std::max(all,d);if(rx::key(names[i]))keys=std::max(keys,d);}z.diag[mi][28]=all;z.diag[mi][29]=keys;}out.row(f.t,f.x,f.y,z.y,z.out,z.loo,z.diag);
   }
  }
 }
 std::cout<<dev<<" frames="<<nf<<" methods="<<modes.size()<<" snapshots="<<snapshots.size()<<" Y_bitwise=PASS identity_bitwise=PASS\n";return 0;
}catch(const std::exception&e){std::cerr<<"RESEARCH_ERROR "<<e.what()<<'\n';return 1;}}
